window.abrirFoto=function(n){const e=window.open("","_blank");if(!e)return void alert("Popup bloqueado pelo navegador.");n=(n||"").trim();try{n=decodeURIComponent(n)}catch(n){}const o=e.document;o.open(),o.write("\n    <html>\n      <head>\n        <title>Visualizar imagem</title>\n        <style>\n          body {\n            margin: 0;\n            background: #111;\n            display: flex;\n            align-items: center;\n            justify-content: center;\n            min-height: 100vh;\n          }\n          img {\n            max-width: 100%;\n            max-height: 100vh;\n            object-fit: contain;\n          }\n        </style>\n      </head>\n      <body></body>\n    </html>\n  "),o.close();const t=o.createElement("img");t.onload=function(){console.log("Imagem carregada:",n)},t.onerror=function(){o.body.innerHTML=`\n      <div style="color:#fff;font-family:Arial;padding:30px;text-align:center;">\n        Erro ao carregar imagem<br><br>\n        ${n}\n      </div>\n    `},t.src=n,o.body.appendChild(t)},window.abrirArquivo=function(n){window.open("https://docs.google.com/gview?embedded=true&url="+encodeURIComponent(n),"_blank")};